import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
import mammoth from "npm:mammoth";
import { Buffer } from "node:buffer";
const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type", "Access-Control-Allow-Methods": "POST, OPTIONS" };
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });
const sections: Record<string, string> = { verse: "Sloka", sloka: "Sloka", chorus: "Refrén", refrain: "Refrén", "refrén": "Refrén", refren: "Refrén", bridge: "Bridge", intro: "Intro", outro: "Outro", "pre-chorus": "Pre-refrén", "pre-refrén": "Pre-refrén", interlude: "Mezihra", mezihra: "Mezihra", hook: "Hook" };
const annotate = (content: string) => content.replace(/
?/g, "
").split("
").map((line) => { const match = line.trim().match(/^\[?\s*(verse|sloka|chorus|refrain|refr[ée]n|bridge|intro|outro|pre-chorus|pre-refr[ée]n|interlude|mezihra|hook)\s*(\d+)?\s*\]?[:\-]?\s*$/i); if (!match) return line; const key = match[1].toLocaleLowerCase("cs-CZ"); return `[${sections[key] ?? match[1]}${match[2] ? ` ${match[2]}` : ""}]`; }).join("
").replace(/
{3,}/g, "

").trim();
const split = (content: string) => { const paragraphs = content.replace(/
?/g, "
").split(/
\s*
/).map((value) => value.trim()).filter(Boolean); if (paragraphs.length < 2) return { stylePrompt: null, lyrics: annotate(content) }; const first = paragraphs.shift() ?? ""; const stylePrompt = first.replace(/^(?:styl(?:ový)?\s*prompt|style\s*prompt|styl)\s*[:\-]\s*/i, "").trim() || null; return { stylePrompt, lyrics: annotate(paragraphs.join("

")) }; };
Deno.serve(async (request) => { if (request.method === "OPTIONS") return new Response("ok", { headers: cors }); if (request.method !== "POST") return json({ error: "Použij POST požadavek." }, 405); const authorization = request.headers.get("Authorization"); const url = Deno.env.get("SUPABASE_URL"); const key = Deno.env.get("SUPABASE_ANON_KEY"); if (!authorization || !url || !key) return json({ error: "Chybí bezpečné připojení k externímu cloudu." }, 401); const supabase = createClient(url, key, { global: { headers: { Authorization: authorization } } }); const { data: { user }, error: authError } = await supabase.auth.getUser(); if (authError || !user) return json({ error: "Neplatné přihlášení." }, 401); const input = await request.json().catch(() => null) as { action?: string; fileName?: string; base64?: string; url?: string; title?: string } | null; if (!input?.action) return json({ error: "Chybí akce." }, 400); let title = input.title?.trim() || "Importovaný text"; let source = ""; let note = ""; if (input.action === "import_docx") { if (!input.base64) return json({ error: "DOCX soubor chybí." }, 400); const extracted = await mammoth.extractRawText({ buffer: Buffer.from(input.base64, "base64") }); source = extracted.value; title = (input.fileName ?? "Importovaný text.docx").replace(/\.docx$/i, "") || title; note = `Importováno z DOCX ${input.fileName ?? ""}`; } else if (input.action === "import_google_document") { const match = input.url?.match(/^https://docs\.google\.com/document/d/([a-zA-Z0-9_-]+)/); if (!match) return json({ error: "Vlož platný odkaz na Google Dokument." }, 400); const response = await fetch(`https://docs.google.com/document/d/${match[1]}/export?format=txt`); if (!response.ok) return json({ error: "Dokument se nepodařilo načíst. Nastav sdílení pro každého s odkazem." }, 400); source = await response.text(); note = "Importováno z Google Dokumentu"; } else return json({ error: "Neznámá importní akce." }, 400); const content = split(source); if (!content.lyrics) return json({ error: "Dokument neobsahuje importovatelný text." }, 400); const { data, error } = await supabase.from("sc_lyrics").insert({ user_id: user.id, title, style_prompt: content.stylePrompt, lyrics: content.lyrics, notes: note }).select("id").single(); return error ? json({ error: error.message }, 400) : json({ id: data.id }); });
